"""Refresh the local render gallery after rendering."""
from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parent
out=root.parent/'renders'
r=json.loads((root/'checks/report.json').read_text())
assemblies=[('bodycam_assembled','Rear bodycam + phone'),('bodycam_exploded','Rear bodycam exploded'),('bodycam_worn','Landscape bodycam upright, 15° down on chest plane'),('bodycam_front_assembled','Front-camera mode: outward screen'),('relay_assembled','Relay + flush power bank'),('relay_open','Relay with lid removed'),('relay_exploded','Relay exploded, integral Pi supports and snap lid'),('finger_clip_assembled','Low U cradle and short fingertip visor'),('finger_clip_exploded','Finger cradle exploded'),('finger_clip_strapped','Black flexible strap over finger, UNDER visor')]
parts=[(p['name'],p['name'].replace('_',' ').title()) for p in r['parts']]
def cards(rows):return ''.join(f'<figure><a href="{n}.png"><img src="{n}.png" alt="{escape(t)}" loading="lazy" width="1600" height="1200"></a><figcaption>{escape(t)}</figcaption></figure>' for n,t in rows)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HANDOFF · CAD render gallery</title><style>body{margin:0;background:#f0f1f2;color:#202830;font:16px/1.5 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:32px}h1{font-size:38px;letter-spacing:.08em;margin:0}h2{margin-top:36px}a{color:#a92329}nav{display:flex;gap:24px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:22px}figure{margin:0;background:white;border-radius:12px;overflow:hidden;box-shadow:0 2px 14px #0001}img{width:100%;height:auto;display:block}figcaption{padding:12px 16px}p{max-width:850px}</style><main><h1>HANDOFF</h1><p>Parametric enclosure kit · 1 November 2026 · screw-free revision</p><p>CAD-derived Blender renders with simplified purchased-part envelopes. Printable parts are shown in their supplied bed orientation. Red lettering illustrates paint fill; black straps are flexible purchased Velcro. The fingertip is an illustrative fit envelope. Click a view for the full 1600 × 1200 PNG.</p><nav><a href="../cad/README.md">CAD and fit guide</a><a href="../cad/VERIFY.md">Verification and dimensions</a><a href="../cad/PRINT_SETTINGS.md">Print settings</a></nav><h2>Assemblies</h2><div class="grid">'''+cards(assemblies)+'''</div><h2>Printable parts</h2><div class="grid">'''+cards(parts)+f'''</div><p>All {len(parts)} STL meshes pass topology checks, and all {len(r['intersections'])} modeled collision, clearance, capture and tolerance checks pass. Physical fit, light pressure, relaxed-hand retention, optical performance, print settings and load strength still require the checks in the CAD guide.</p></main></html>'''
(out/'index.html').write_text(html)
(out/'README.md').write_text('# HANDOFF renders\n\nOpen [index.html](index.html) for the complete gallery. All 23 PNGs are 1600 × 1200, generated in Blender from OpenSCAD geometry. The thirteen STL layouts show bed orientation. Assembly renders use simplified component envelopes; screen, finger and flexible webbing details are illustrative.\n\n'+ '\n'.join(f'- [{t}]({n}.png)' for n,t in assemblies)+'\n\nSee [CAD instructions](../cad/README.md), [verification](../cad/VERIFY.md), and [print settings](../cad/PRINT_SETTINGS.md).\n')
print('Gallery updated')
